// Every snapshot as a small map (site/data/thumbs.json, generated by tools/build_slices.py), filterable by era.
(() => {
  "use strict";
  const list = document.getElementById("eras");
  list.innerHTML = Array.from({ length: 12 }, () => '<li class="era"><div class="era-ph"></div></li>').join("");

  fetch("data/meta.json").then((r) => r.json()).then((m) => {
    document.querySelectorAll("[data-meta]").forEach((el) => {
      const v = m[el.dataset.meta];
      if (v != null) el.textContent = typeof v === "number" ? v.toLocaleString("en-US") : v;
    });
  }).catch(() => {});

  fetch("data/thumbs.json").then((r) => r.json()).then(({ w, h, thumbs }) => {
    list.innerHTML = thumbs.map((t) => `
      <li class="era" data-year="${t.year}">
        <a href="map.html?year=${t.year}">
          <svg viewBox="0 0 ${w} ${h}" aria-hidden="true" focusable="false">${t.layers.map((l) => `<path d="${l.d}" fill="hsl(${l.h} 42% 58%)"/>`).join("")}</svg>
          <b>${t.label}</b>
          <span>${t.regions.toLocaleString("en-US")} named regions</span>
        </a>
      </li>`).join("");
  }).catch(() => {
    list.innerHTML = '<li>The snapshots could not load. <a href="map.html">Open the atlas</a> instead.</li>';
  });

  document.querySelectorAll("[data-range]").forEach((b) => b.addEventListener("click", () => {
    document.querySelectorAll("[data-range]").forEach((o) => o.setAttribute("aria-pressed", String(o === b)));
    const [lo, hi] = b.dataset.range === "all" ? [-Infinity, Infinity] : b.dataset.range.split(",").map(Number);
    list.querySelectorAll(".era").forEach((li) => {
      const y = Number(li.dataset.year);
      li.hidden = !(y >= lo && y <= hi);
    });
  }));
})();
